and do NOT output anything else.

Answer:
<CODE>
from pymtl3 import *

class TopModule( Component ):

  def construct( s ):

    # Port-based interface

    s.in_ = InPort (8)
    s.out = OutPort(8)

    # Combinational logic

    @update
    def up():
      s.out @= s.in_ + 1
