extern "C" {{
  typedef struct {{

    // Exposed port interface
{port_defs}

    // The following variables have a _cffi_ prefix to avoid name conflicts
    // with the port names.

    // Verilator model
    void * _cffi_model;

    // Verilator simulation context
    void * _cffi_context_ptr;

    // VCD state
